    # adjacent non-background object's color, or with the background if none.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            neighbors = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != color:
                    neighbors.append(grid[rr][cc])
            # A singleton mark is one whose same-color neighbors are absent.
            same = any(0 <= r + dr < h and 0 <= c + dc < w and
                       grid[r + dr][c + dc] == color
                       for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)))
            if not same:
                objs = [x for x in neighbors if x != bg]
                out[r][c] = objs[0] if objs else bg
    return out
