def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append((color, cells))

    # Rectangular objects may contain a one-cell intrusion; restore the
    # rectangle's dominant color throughout its bounding box.
    for color, cells in components:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        area = (r1-r0+1) * (c1-c0+1)
        if len(cells) >= 4 and len(cells) / area >= 0.75:
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    out[r][c] = color

    # Remove isolated stray marks outside the rectangular objects.
    for color, cells in components:
        if len(cells) == 1:
            r, c = cells[0]
            if out[r][c] == color:
                out[r][c] = bg
    return out
